            if row[0] != 0 and all(v == row[0] for v in row)]
    if bars:
        period = len(bars)
        palette = {r % period: color for r, color in bars}
        return [[palette[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal strokes of slope +1 encode a repeating diagonal tile. Each
    # stroke lies on a constant (column - row) offset; reduce offsets modulo
    # the number of distinct strokes to recover the pattern's phases.
    diagonals = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                diagonals[c - r] = color
    period = len(diagonals)
    if not period:
        return [row[:] for row in grid]
    palette = {offset % period: color for offset, color in diagonals.items()}
    return [[palette[(c - r) % period] for c in range(w)] for r in range(h)]

